import { createHash } from 'crypto';
import sharp from 'sharp';
import type {
  ImageCapabilities, ImageGenerateRequest, ImageGenerateResult, ImageProvider,
  VideoCapabilities, VideoProvider, VideoStatus, VideoSubmitRequest,
} from '../types';

/**
 * TEST-ONLY providers. They produce real, valid files (so storage, scanning, re-encoding and playback are exercised
 * for real) but nothing is generated by a model. The API refuses to select them unless APP_ENV=test, and they are
 * never offered as a product feature.
 */

type ImageScript = Error | ((req: ImageGenerateRequest) => ImageGenerateResult | Promise<ImageGenerateResult>);

function colorFor(seed: string): [string, string] {
  const h = createHash('sha1').update(seed).digest();
  const c = (o: number) => [h[o]!, h[o + 1]!, h[o + 2]!].map((v) => v.toString(16).padStart(2, '0')).join('');
  return [`#${c(0)}`, `#${c(3)}`];
}

export class FakeImageProvider implements ImageProvider {
  readonly name = 'fake';
  readonly capabilities: ImageCapabilities = {
    nativeSizes: [
      { width: 1024, height: 1024 },
      { width: 1536, height: 1024 },
      { width: 1024, height: 1536 },
    ],
    maxImagesPerRequest: 4,
    edit: true,
    inputFidelity: true,
  };
  readonly requests: ImageGenerateRequest[] = [];
  configured = true;
  private queue: ImageScript[] = [];

  isConfigured() {
    return this.configured;
  }
  enqueue(...items: ImageScript[]) {
    this.queue.push(...items);
  }
  reset() {
    this.queue = [];
    this.requests.length = 0;
    this.configured = true;
  }

  async generate(req: ImageGenerateRequest): Promise<ImageGenerateResult> {
    this.requests.push(req);
    const next = this.queue.shift();
    if (next instanceof Error) throw next;
    if (next) return next(req);
    const images = [];
    for (let i = 0; i < req.count; i++) {
      if (req.source) {
        // An "edit": the supplied photo, resized (a stand-in for a model edit).
        images.push({ data: await sharp(req.source.data).resize(req.size.width, req.size.height, { fit: 'cover' }).png().toBuffer(), mime: 'image/png' });
      } else {
        const [a, b] = colorFor(`${req.prompt}#${i}`);
        const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${req.size.width}" height="${req.size.height}"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient></defs><rect width="100%" height="100%" fill="url(#g)"/></svg>`;
        images.push({ data: await sharp(Buffer.from(svg)).png().toBuffer(), mime: 'image/png' });
      }
    }
    return { images, model: `fake:${req.model}`, usage: { inputTokens: Math.ceil(req.prompt.length / 4), outputTokens: 1000 * req.count }, revisedPrompt: undefined };
  }
}

/** A structurally valid (empty) MP4: enough for type detection, storage and the player to treat it as a video file. */
export function fakeMp4(): Buffer {
  const ftyp = Buffer.concat([Buffer.from([0, 0, 0, 0x18]), Buffer.from('ftypisom'), Buffer.from([0, 0, 2, 0]), Buffer.from('isommp42')]);
  const free = Buffer.concat([Buffer.from([0, 0, 0x08, 0x00]), Buffer.from('free'), Buffer.alloc(0x800 - 8)]);
  return Buffer.concat([ftyp, free]);
}

export class FakeVideoProvider implements VideoProvider {
  readonly name = 'fake';
  readonly capabilities: VideoCapabilities = {
    seconds: [4, 8, 12],
    sizes: { '9:16': { width: 720, height: 1280 }, '16:9': { width: 1280, height: 720 }, '1:1': { width: 720, height: 720 } },
    imageToVideo: true,
    thumbnail: true,
  };
  readonly submits: VideoSubmitRequest[] = [];
  readonly polls: string[] = [];
  configured = true;
  /** States returned by successive status() calls of a job; the last one repeats. Default: one poll "in progress", then done. */
  statusPlan: VideoStatus[] = [{ state: 'in_progress', progress: 40 }, { state: 'completed', progress: 100 }];
  submitError: Error | null = null;
  downloadError: Error | null = null;
  private counter = 0;
  private pollCount = new Map<string, number>();

  isConfigured() {
    return this.configured;
  }
  reset() {
    this.submits.length = 0;
    this.polls.length = 0;
    this.configured = true;
    this.statusPlan = [{ state: 'in_progress', progress: 40 }, { state: 'completed', progress: 100 }];
    this.submitError = null;
    this.downloadError = null;
    this.pollCount.clear();
  }

  async submit(req: VideoSubmitRequest) {
    if (this.submitError) throw this.submitError;
    this.submits.push(req);
    return { ref: `fakevid_${++this.counter}` };
  }
  async status(ref: string): Promise<VideoStatus> {
    this.polls.push(ref);
    const n = this.pollCount.get(ref) ?? 0;
    this.pollCount.set(ref, n + 1);
    return this.statusPlan[Math.min(n, this.statusPlan.length - 1)]!;
  }
  async download() {
    if (this.downloadError) throw this.downloadError;
    return { data: fakeMp4(), mime: 'video/mp4' };
  }
  async thumbnail(): Promise<Buffer | null> {
    return sharp({ create: { width: 480, height: 270, channels: 3, background: '#335577' } }).png().toBuffer();
  }
}
